3: namespace App\Http\Middleware;
4: 
5: use Closure;
6: use Illuminate\Http\Request;
7: use Illuminate\Support\Facades\Auth;
8: use Symfony\Component\HttpFoundation\Response;
9: 
10: class AuthenticateAnyActor
11: {
12:     /**
13:      * Handle an incoming request.
14:      *
15:      * Checks whether the request is authenticated by any of the supported
16:      * guard drivers (sanctum, specialist, portal). When exactly one guard has
17:      * a valid token, that guard becomes the default for the request so that
18:      * $request->user() / auth()->user() resolves the intended actor.
19:      *
20:      * When multiple guards have valid tokens simultaneously, the default guard
21:      * is intentionally left unchanged. This prevents actor confusion where a
22:      * user holding tokens for multiple guard types could be resolved to the
23:      * wrong actor type by controllers using $request->user(). Route-specific
24:      * middleware (auth:sanctum, auth:specialist, auth:portal) and controllers
25:      * that need a specific actor should use explicit guard resolution
26:      * (e.g. auth('specialist')->user()).
27:      */
28:     public function handle(Request $request, Closure $next): Response
29:     {
30:         $guards = ['sanctum', 'specialist', 'portal'];
31:         $authenticatedGuards = [];
32: 
33:         foreach ($guards as $guard) {
34:             if (Auth::guard($guard)->check()) {
35:                 $authenticatedGuards[] = $guard;
36:             }
37:         }
38: 
39:         if (empty($authenticatedGuards)) {
40:             return response()->json(['message' => 'Unauthenticated.'], 401);
41:         }
42: 
43:         // Only set the default guard when exactly one guard is authenticated.
44:         // Multiple simultaneous tokens are ambiguous — do not silently pick one.
45:         if (count($authenticatedGuards) === 1) {
46:             Auth::shouldUse($authenticatedGuards[0]);
47:         }
48: 
49:         return $next($request);
50:     }
51: }

