682:                 'provider_reference' => $providerReference ?? 'MANUAL-REF-' . strtoupper(Str::random(8)),
683:                 'paid_at' => now(),
684:                 'notes' => 'Refund for transaction ' . $original->internal_reference,
685:             ]);
